pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize "sliver" residuals that are 
    // too small to fit common items (10-20), while penalizing the creation of new bins 
    // unless the fit is extremely poor.

    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the post_residual is in the range (0..10), 
    // it is highly likely to be wasted space. Penalize these gaps exponentially.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // 2. Lookahead optimization: If a future item is known, prefer leaving enough space 
    // to accommodate it. If post_residual is less than next_item_size, we penalize 
    // the placement to favor bins that can hold both current and next items.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // 3. Open bins pressure: If this bin is a new bin (bin_residual == bin_capacity), 
    // only choose it if the current best existing bin is truly terrible.
    if bin_residual == bin_capacity {
        // High base penalty for opening a new bin
        score += 45.0;

        // Scale penalty based on how many bins are already open to prevent fragmentation
        score += open_bins_count as f64 * 2.0;
    } else {
        // Reward bins that are closer to the mean residual to keep bin fill levels balanced
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.5;
    }

    // 4. Urgency: If this is the only bin that fits, we should prioritize it 
    // regardless of the residual to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

