pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize the score to select the bin.
    // 1. Base cost is the remaining space (Best Fit principle).
    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead space":
    // Small gaps (1-9) are notoriously hard to fill. Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead optimization:
    // If we know the next item, penalize bins that can't fit it after this placement.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // 4. Pressure management:
    // If this is the only bin that fits the item (fitting_bins_count == 1), 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // 5. New bin management:
    // If this is a new bin (bin_residual == bin_capacity), only choose it if 
    // the penalty for current open bins is high (e.g., they all create bad dead space).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless open_bins_count is low.
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // 6. Global efficiency:
    // Favor bins that align with the global mean residual to keep bin levels balanced.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    score
}
